TRUNCATE TABLE alert_configurations CASCADE;
TRUNCATE TABLE notifications CASCADE;
TRUNCATE TABLE report_schedule_recipients, report_schedules, report_results, report_requests CASCADE;
TRUNCATE TABLE audit_logs, login_logs, user_sessions, password_requests CASCADE;
TRUNCATE TABLE employee_study, training_plan_details, training_plans CASCADE;
TRUNCATE TABLE course_skills, courses, skills CASCADE;
TRUNCATE TABLE effort_projects, project_assignments, project_resource_requests CASCADE;
TRUNCATE TABLE budget_allocations, budgets CASCADE;
TRUNCATE TABLE projects, contracts, service_line_rates, service_lines, customers CASCADE;
TRUNCATE TABLE employee_organizations CASCADE;
TRUNCATE TABLE sub_teams, teams, groups CASCADE;
TRUNCATE TABLE users CASCADE;
TRUNCATE TABLE employees CASCADE;
TRUNCATE TABLE role_permissions, permissions, roles CASCADE;
TRUNCATE TABLE positions, job_levels CASCADE;

