-- ============================================================
-- KIỂM TRA SỐ LƯỢNG BẢN GHI
-- ============================================================
SELECT table_name, COUNT(*) AS rows FROM (
  SELECT 'roles' AS table_name FROM roles UNION ALL
  SELECT 'permissions' FROM permissions UNION ALL
  SELECT 'employees' FROM employees UNION ALL
  SELECT 'users' FROM users UNION ALL
  SELECT 'groups' FROM groups UNION ALL
  SELECT 'teams' FROM teams UNION ALL
  SELECT 'sub_teams' FROM sub_teams UNION ALL
  SELECT 'customers' FROM customers UNION ALL
  SELECT 'service_lines' FROM service_lines UNION ALL
  SELECT 'contracts' FROM contracts UNION ALL
  SELECT 'projects' FROM projects UNION ALL
  SELECT 'project_assignments' FROM project_assignments UNION ALL
  SELECT 'effort_projects' FROM effort_projects UNION ALL
  SELECT 'budgets' FROM budgets UNION ALL
  SELECT 'courses' FROM courses UNION ALL
  SELECT 'training_plans' FROM training_plans UNION ALL
  SELECT 'employee_study' FROM employee_study UNION ALL
  SELECT 'user_sessions' FROM user_sessions UNION ALL
  SELECT 'login_logs' FROM login_logs UNION ALL
  SELECT 'audit_logs' FROM audit_logs UNION ALL
  SELECT 'report_requests' FROM report_requests UNION ALL
  SELECT 'notifications' FROM notifications UNION ALL
  SELECT 'alert_configurations' FROM alert_configurations
) t GROUP BY table_name ORDER BY table_name;


-- gỡ lock
UPDATE users 
SET is_locked = false, failed_attempts = 0, locked_until = null
WHERE company_email = 'email_cần_unlock@bosch.com';
